pub unsafe extern "C" fn ml_tirust_last_error(out: *mut u8, capacity: usize) -> usize {
    LAST_ERROR.with(|e| {
        let e = e.borrow();
        if !out.is_null() && capacity > 0 {
            let n = e.len().min(capacity - 1);
            unsafe {
                write(out, &e.as_bytes()[..n]);
                out.add(n).write(0);
            }
        }
        e.len() + 1
    })
}
